import re
import json
import sys

def parse_script(text: str):
    nodes_dict = {}
    edges = []

    # Normalize line endings
    text = text.replace('\r\n', '\n')

    # Split text into sections by [NodeID]
    # We look for [NodeID] at the start of a line or start of string
    sections = re.split(r'\n(?=\[)', text)
    if not sections or (len(sections) == 1 and not sections[0].strip().startswith('[')):
        # Try without the newline if it's the very first line
        if text.strip().startswith('['):
            sections = re.split(r'\n(?=\[)', text)
        else:
            return {"nodes": [], "edges": []}

    first_node_id = None

    for section in sections:
        section = section.strip()
        if not section:
            continue

        lines = section.split('\n')
        header_match = re.match(r'\[(.*?)\]', lines[0])
        if not header_match:
            continue

        node_id = header_match.group(1).strip()
        if first_node_id is None:
            first_node_id = node_id

        content_lines = [l.strip() for l in lines[1:] if l.strip()]

        if not content_lines:
            nodes_dict[node_id] = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "line"
            }
            continue

        # Determine if it's a choice node or line node
        is_choice = any(re.match(r'^\d+\.', l) for l in content_lines)

        if is_choice:
            nodes_dict[node_id] = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            }
            for line in content_lines:
                # Format: Digit. Text -> Target
                m = re.match(r'^\d+\.\s*(.*?)\s*->\s*(.*)$', line)
                if m:
                    edges.append({
                        "from": node_id,
                        "to": m.group(2).strip(),
                        "text": m.group(1).strip()
                    })
        else:
            # Line node
            # Format: Speaker: Text -> Target
            line = content_lines[0]
            # Match speaker, text and target. Text can contain colons but the last -> is the separator for target.
            # Using rfind for -> might be safer but regex usually works.
            # We assume the format Speaker: Text -> Target
            m = re.match(r'^(.*?):\s*(.*)\s*->\s*(.*?)$', line)
            if m:
                nodes_dict[node_id] = {
                    "id": node_id,
                    "text": m.group(2).strip(),
                    "speaker": m.group(1).strip(),
                    "type": "line"
                }
                edges.append({
                    "from": node_id,
                    "to": m.group(3).strip(),
                    "text": ""
                })
            else:
                # Fallback if no speaker or weird format
                m = re.match(r'^(.*)\s*->\s*(.*?)$', line)
                if m:
                    nodes_dict[node_id] = {
                        "id": node_id,
                        "text": m.group(1).strip(),
                        "speaker": "",
                        "type": "line"
                    }
                    edges.append({
                        "from": node_id,
                        "to": m.group(2).strip(),
                        "text": ""
                    })
                else:
                    nodes_dict[node_id] = {
                        "id": node_id,
                        "text": line,
                        "speaker": "",
                        "type": "line"
                    }

    # Add missing nodes (like 'End')
    referenced_node_ids = set()
    for edge in edges:
        referenced_node_ids.add(edge['to'])

    for ref_id in referenced_node_ids:
        if ref_id not in nodes_dict:
            nodes_dict[ref_id] = {
                "id": ref_id,
                "text": "",
                "speaker": "",
                "type": "line"
            }

    # Reachability check from the first node
    if first_node_id:
        reachable = {first_node_id}
        queue = [first_node_id]
        while queue:
            curr = queue.pop(0)
            for edge in edges:
                if edge['from'] == curr and edge['to'] not in reachable:
                    reachable.add(edge['to'])
                    queue.append(edge['to'])

        final_nodes = [nodes_dict[nid] for nid in sorted(nodes_dict.keys()) if nid in reachable]
        final_edges = [edge for edge in edges if edge['from'] in reachable]
    else:
        final_nodes = [nodes_dict[nid] for nid in sorted(nodes_dict.keys())]
        final_edges = edges

    return {"nodes": final_nodes, "edges": final_edges}

def main():
    try:
        with open('/app/script.txt', 'r') as f:
            content = f.read()
    except FileNotFoundError:
        return

    graph = parse_script(content)

    with open('/app/dialogue.json', 'w') as f:
        json.dump(graph, f, indent=2)

    with open('/app/dialogue.dot', 'w') as f:
        f.write("digraph G {\n")
        f.write("  rankdir=LR;\n")
        f.write("  node [fontname=\"Arial\"];\n")
        for node in graph['nodes']:
            label = node['id']
            if node['type'] == 'line' and node['text']:
                spk = f"{node['speaker']}: " if node['speaker'] else ""
                label = f"[{node['id']}]\\n{spk}{node['text']}"
            elif node['type'] == 'choice':
                label = f"[{node['id']}] (Choice)"

            clean_label = label.replace('"', '\\"').replace('\n', '\\n')
            shape = "box" if node['type'] == 'line' else "diamond"
            f.write(f'  "{node["id"]}" [label="{clean_label}", shape={shape}];\n')

        for edge in graph['edges']:
            label = edge['text'].replace('"', '\\"').replace('\n', '\\n')
            if label:
                f.write(f'  "{edge["from"]}" -> "{edge["to"]}" [label="{label}"];\n')
            else:
                f.write(f'  "{edge["from"]}" -> "{edge["to"]}";\n')
        f.write("}\n")

if __name__ == "__main__":
    main()

